<?php
declare(strict_types=1);
require dirname(__DIR__).'/config/bootstrap.php';

use InaudisVote\Core\Authorization;
use InaudisVote\Core\Csrf;
use InaudisVote\Core\Navigation;
use InaudisVote\Services\OrganizationService;
use InaudisVote\Services\UserService;

$user=Authorization::requireRoles(['admin']);
$error=null;$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Csrf::validate($_POST['_csrf']??null))$error='La sesión del formulario venció. Recarga la página e intenta nuevamente.';
    else try{
        $action=(string)($_POST['action']??'create');$userId=(int)($_POST['user_id']??0);
        if($action==='toggle'){UserService::toggleStatus($userId,$user);$message='Estado del acceso actualizado.';}
        elseif($action==='update'){UserService::update($userId,$_POST,$user);$message='Datos del usuario actualizados.';}
        elseif($action==='reset_password'){UserService::resetPassword($userId,(string)($_POST['password']??''),(string)($_POST['password_confirmation']??''),$user);$message='Contraseña restablecida correctamente.';}
        else{$createdRole=(string)($_POST['role']??'organizer');UserService::create($_POST,$user);$message=$createdRole==='witness'?'Ministro de Fe creado. Ahora puedes asignarlo desde Fiscalización.':($createdRole==='organizer'?'Organizador creado. Ahora puedes asignarlo desde el Centro de control.':'Administrador creado correctamente.');}
    }catch(Throwable $exception){$error=$exception->getMessage();}
}
$users=UserService::allForActor($user);$organizations=$user['role']==='admin'?OrganizationService::all():[];
$roleLabels=['admin'=>'Administrador DEMOCRA','organizer'=>'Organizador','witness'=>'Ministro de Fe'];
$statusLabels=['active'=>'Activo','inactive'=>'Inactivo'];
?>
<!doctype html><html lang="es"><head><link rel="icon" type="image/png" href="/assets/democra-mark.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Equipo y accesos | DEMOCRA</title><link rel="stylesheet" href="/assets/democra-base.css"><link rel="stylesheet" href="/assets/democra.css"></head><body class="vota-ui"><div class="v-shell">
<?php Navigation::sidebar($user,'users'); ?>
<div class="v-main"><header class="v-topbar"><span class="v-muted">Administración de accesos</span><span style="flex:1"></span><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content">
<div class="v-headrow"><div><div class="v-kicker">Accesos y responsabilidades</div><h1 class="v-title">Equipo</h1><div class="v-accent-line"></div><p class="v-subtitle"><?=$user['role']==='admin'?'Administra todos los usuarios, clientes, roles y credenciales de la plataforma.':'Administra los accesos operativos de tu cliente.'?></p></div></div>
<?php if($message):?><div class="v-alert v-alert-ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?>
<details class="v-disclosure user-create-panel"><summary>Crear un nuevo acceso</summary><div><p class="v-muted">Crear un usuario no lo asigna automáticamente a una votación. Las asignaciones se realizan en el Centro de control o en Fiscalización.</p><form method="post" class="user-form-grid"><?=Csrf::input()?><input type="hidden" name="action" value="create"><label><span>Nombre</span><input class="v-field" name="name" required maxlength="150"></label><label><span>Correo electrónico</span><input class="v-field" name="email" type="email" required></label><label><span>Contraseña inicial</span><input class="v-field" name="password" type="password" minlength="8" required autocomplete="new-password"></label><label><span>Rol</span><select class="v-field" name="role"><option value="organizer">Organizador</option><option value="witness">Ministro de Fe</option><?php if($user['role']==='admin'):?><option value="admin">Administrador DEMOCRA</option><?php endif;?></select></label><?php if($user['role']==='admin'):?><label><span>Cliente</span><select class="v-field" name="organization_id"><option value="">Sin cliente / Administrador</option><?php foreach($organizations as $organization):?><option value="<?=$organization['id']?>"><?=htmlspecialchars($organization['name'])?></option><?php endforeach;?></select></label><?php endif;?><div class="user-form-submit"><button class="v-btn v-btn-orange">Crear usuario</button></div></form></div></details>
<section class="v-card v-pad users-card"><div class="v-section-head"><h2 style="margin:0">Accesos</h2><span class="v-muted"><?=count($users)?> usuarios</span></div><div class="v-table-wrap"><table class="v-table users-table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol</th><th>Cliente</th><th>Estado</th><th>Administrar</th></tr></thead><tbody>
<?php foreach($users as $account):?><tr><td><strong><?=htmlspecialchars($account['name'])?></strong></td><td class="user-email"><?=htmlspecialchars($account['email'])?></td><td><?=htmlspecialchars($roleLabels[$account['role']]??$account['role'])?></td><td><?=htmlspecialchars($account['organization_name']?:'DEMOCRA')?></td><td><span class="v-status <?=$account['status']==='active'?'v-status-open':'v-status-draft'?>"><?=htmlspecialchars($statusLabels[$account['status']]??$account['status'])?></span></td><td>
<details class="user-actions"><summary>Administrar</summary><div class="user-actions-menu"><details><summary>Editar datos</summary><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="update"><input type="hidden" name="user_id" value="<?=$account['id']?>"><label><span>Nombre</span><input class="v-field" name="name" value="<?=htmlspecialchars($account['name'])?>" maxlength="150" required></label><label><span>Email</span><input class="v-field" type="email" name="email" value="<?=htmlspecialchars($account['email'])?>" required></label><?php if($user['role']==='admin'&&(int)$account['id']!==(int)$user['id']):?><label><span>Rol</span><select class="v-field" name="role"><?php foreach($roleLabels as $roleValue=>$roleLabel):?><option value="<?=$roleValue?>" <?=$account['role']===$roleValue?'selected':''?>><?=$roleLabel?></option><?php endforeach;?></select></label><label><span>Cliente</span><select class="v-field" name="organization_id"><option value="">Sin cliente / Administrador</option><?php foreach($organizations as $organization):?><option value="<?=$organization['id']?>" <?=(int)$account['organization_id']===(int)$organization['id']?'selected':''?>><?=htmlspecialchars($organization['name'])?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="role" value="<?=htmlspecialchars($account['role'])?>"><?php endif;?><button class="v-btn v-btn-primary">Guardar cambios</button></form></details>
<details><summary>Restablecer contraseña</summary><form method="post" class="v-stack" data-confirm="¿Restablecer la contraseña de este usuario?"><?=Csrf::input()?><input type="hidden" name="action" value="reset_password"><input type="hidden" name="user_id" value="<?=$account['id']?>"><label><span>Nueva contraseña</span><input class="v-field" type="password" name="password" minlength="8" required autocomplete="new-password"></label><label><span>Confirmar contraseña</span><input class="v-field" type="password" name="password_confirmation" minlength="8" required autocomplete="new-password"></label><button class="v-btn v-btn-orange">Restablecer contraseña</button></form></details>
<?php if((int)$account['id']!==(int)$user['id']):?><form method="post" data-confirm="¿<?= $account['status']==='active'?'Desactivar':'Activar' ?> este acceso?"><?=Csrf::input()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="user_id" value="<?=$account['id']?>"><button class="v-btn <?=$account['status']==='active'?'v-btn-danger':'v-btn-outline'?>"><?=$account['status']==='active'?'Desactivar acceso':'Activar acceso'?></button></form><?php endif;?></div></details>
</td></tr><?php endforeach;?></tbody></table></div></section>
</main></div></div><script src="/assets/democra-confirm.js" defer></script></body></html>
